revert("userisBuyCarTypeOf");
}
uint256 usdtAmount = carPrices[typeOf-1];
USDT.safeTransferFrom(user,address(this),usdtAmount);
allowRecommend[user] = true;
userisBuyCarTypeOf[user][typeOf] = true;
